import{config}from'./config.js';import{loadRuntime,renderBlocks,translate,navigation}from'./site-runtime.js';import{safeStorage,initialiseConsent}from'./tracking.js';
const params=new URLSearchParams(location.search),language=params.get('lang')||safeStorage.get('kindora-language')||'en';document.documentElement.lang=['en','de','fr','es','pt'].includes(language)?language:'en';
initialiseConsent();try{await loadRuntime();const response=await fetch(`${config.apiBase}/page?slug=${encodeURIComponent(params.get('slug')||'')}`);if(!response.ok)throw new Error();const page=await response.json();document.title=translate(page.title)+' · Kindora Paws';document.getElementById('page-title').textContent=translate(page.title);renderBlocks(document.getElementById('page-blocks'),page.blocks);navigation();}catch{document.getElementById('page-title').textContent='Page unavailable';}
